use ldk_node::Builder;
use ldk_node::bitcoin::Network;
use ldk_node::lightning_invoice::Bolt11Invoice;
use std::str::FromStr;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let mut builder = Builder::new();
    builder.set_network(Network::Regtest);
    builder.set_esplora_server(
        "http://localhost:3002".to_string()
    );

    let node = builder.build()?;
    node.start()?;

    println!(
        "Node started. Node ID: {}",
        node.node_id()
    );

    println!(
        "Funding address: {}",
        node.onchain_payment().new_address()?
    );

    // Keep running, listen for events
    loop {
        let event = node.wait_next_event();
        println!("Event: {:?}", event);
        node.event_handled();
    }
}

use ldk_node::Node;
use ldk_node::payment::Bolt11Payment;

pub fn create_invoice(
    node: &Node,
    amount_sats: u64,
    description: &str,
) -> anyhow::Result<String> {
    let invoice = node
        .bolt11_payment()
        .receive(
            amount_sats * 1000, // convert to msats
            description,
            3600,              // 1 hour expiry
        )?;

    Ok(invoice.to_string())
}

use lightning::events::Event;

pub fn handle_event(event: Event, tx: &tokio::sync::broadcast::Sender<String>) {
    if let Event::PaymentClaimable { payment_hash, amount_msat, .. } = event {
        let sats = amount_msat / 1_000;
        let payload = format!("event: paid\ndata: {}:{}\n\n", payment_hash, sats);
        let _ = tx.send(payload);
    }
}

import 'package:bdk_flutter/bdk_flutter.dart';

class WalletService {
  late Wallet _wallet;
  late Blockchain _blockchain;

  Future<void> init() async {
    final mnemonic = await Mnemonic.create(WordCount.words12);

    final descriptors = await _buildDescriptors(mnemonic);

    _blockchain = await Blockchain.create(
      config: BlockchainConfig.esplora(
        config: EsploraConfig(
          baseUrl: 'https://blockstream.info/testnet/api',
          stopGap: 10,
        ),
      ),
    );

    _wallet = await Wallet.create(
      descriptor: descriptors.$1,
      changeDescriptor: descriptors.$2,
      network: Network.testnet,
      databaseConfig: const DatabaseConfig.memory(),
    );
  }

  Future<(Descriptor, Descriptor)> _buildDescriptors(
      Mnemonic mnemonic) async {
    final secretKey = await DescriptorSecretKey.create(
      network: Network.testnet,
      mnemonic: mnemonic,
    );

    final external = await Descriptor.newBip84(
      secretKey: secretKey,
      network: Network.testnet,
      keychainKind: KeychainKind.external,
    );

    final internal = await Descriptor.newBip84(
      secretKey: secretKey,
      network: Network.testnet,
      keychainKind: KeychainKind.internal,
    );

    return (external, internal);
  }

  Future<String> getReceiveAddress() async {
    final addressInfo = await _wallet.getAddress(
      addressIndex: const AddressIndex.increase(),
    );
    return addressInfo.address.asString();
  }

  Future<int> getBalance() async {
    await _wallet.sync(blockchain: _blockchain);
    final balance = await _wallet.getBalance();
    return balance.total.toInt();
  }

  Future<List<TransactionDetails>> getTransactions() async {
    return await _wallet.listTransactions(includeRaw: false);
  }
}

