import 'package:bdk_flutter/bdk_flutter.dart';

class VaultService {
  final Wallet _wallet;
  final Blockchain _blockchain;

  VaultService(this._wallet, this._blockchain);

  /// Creates a CLTV-locked output that can only be spent
  /// after [lockUntilBlock] block height is reached.
  Future<String> createVault({
    required int amountSats,
    required int lockUntilBlock,
  }) async {
    final addressInfo = await _wallet.getAddress(
      addressIndex: const AddressIndex.increase(),
    );

    // Build CLTV script:
    // OP_lockUntilBlock OP_CHECKLOCKTIMEVERIFY OP_DROP
    // OP_DUP OP_HASH160 <pubKeyHash> OP_EQUALVERIFY OP_CHECKSIG
    final script = await ScriptBuf.withCapacity(50);
    await script.pushInt(lockUntilBlock);
    await script.pushOpcode(Opcode.opCheckLockTimeVerify);
    await script.pushOpcode(Opcode.opDrop);
    await script.pushOpcode(Opcode.opDup);
    await script.pushOpcode(Opcode.opHash160);
    await script.pushSlice(
      await addressInfo.address.toScriptPubkey().toBytes(),
    );
    await script.pushOpcode(Opcode.opEqualVerify);
    await script.pushOpcode(Opcode.opCheckSig);

    final txBuilder = TxBuilder();
    final (psbt, _) = await txBuilder
        .addRecipient(
          script: script,
          amount: BigInt.from(amountSats),
        )
        .feeRate(feeRate: 2.0)
        .finish(_wallet);

    final signedPsbt = await _wallet.sign(psbt: psbt);
    final tx = await signedPsbt.extractTx();
    final txid = await _blockchain.broadcast(transaction: tx);

    return txid;
  }

  bool isVaultUnlocked(int lockUntilBlock, int currentBlock) {
    return currentBlock >= lockUntilBlock;
  }
}

class StreakService {
  Future<int> updateStreak(DateTime now, SharedPreferences prefs) async {
    final lastDeposit = prefs.getString('last_deposit_at');
    final current = prefs.getInt('current_streak') ?? 0;
    final next = _isConsecutive(lastDeposit, now) ? current + 1 : 1;

    await prefs.setString('last_deposit_at', now.toIso8601String());
    await prefs.setInt('current_streak', next);
    return next;
  }
}

import 'package:ldk_node/ldk_node.dart';

class LightningService {
  late Node _node;

  Future<void> init() async {
    final builder = Builder()
      ..setNetwork(Network.testnet)
      ..setEsploraServer('https://blockstream.info/testnet/api')
      ..setGossipSourceRgs(
        'https://rapidsync.lightningdevkit.org/testnet/snapshot',
      );

    _node = await builder.build();
    await _node.start();
  }

  Future<String> receivePayment({
    required int amountSats,
    required String description,
  }) async {
    final invoice = await _node.bolt11Payment().receive(
      amountMsat: amountSats * 1000,
      description: description,
      expirySecs: 3600,
    );
    return invoice.toString();
  }

  Future<void> waitForPayment(String paymentHash) async {
    await for (final event in _node.eventHandler()) {
      if (event is PaymentReceived &&
          event.paymentHash.toString() == paymentHash) {
        break;
      }
    }
  }

  Future<void> dispose() async {
    await _node.stop();
  }
}

