use bitcoin::psbt::Psbt;
use bitcoin::consensus::deserialize;
use std::str::FromStr;

fn main() -> anyhow::Result<()> {
    let args: Vec<String> = std::env::args().collect();

    if args.len() < 2 {
        eprintln!("Usage: psbt-signer <hex-encoded-psbt>");
        std::process::exit(1);
    }

    let psbt_hex = &args[1];
    let psbt_bytes = hex::decode(psbt_hex)?;
    let psbt: Psbt = deserialize(&psbt_bytes)?;

    println!("=== PSBT Summary ===");
    println!("Version: {}", psbt.unsigned_tx.version);
    println!("Locktime: {}", psbt.unsigned_tx.lock_time);
    println!();

    println!("--- Inputs ({}) ---", psbt.inputs.len());
    for (i, input) in psbt.inputs.iter().enumerate() {
        println!("  Input {}", i);
        if let Some(utxo) = &input.witness_utxo {
            println!(
                "    Value: {} sats",
                utxo.value.to_sat()
            );
        }
        if let Some(origin) = input.tap_key_origins.values().next() {
            println!(
                "    Derivation: {}",
                origin.1.derivation_path()
            );
        }
    }

    println!();
    println!("--- Outputs ({}) ---", psbt.outputs.len());
    for (i, _output) in psbt.outputs.iter().enumerate() {
        let txout = &psbt.unsigned_tx.output[i];
        println!(
            "  Output {}: {} sats",
            i,
            txout.value.to_sat()
        );
    }

    Ok(())
}

