use bitcoin::psbt::Psbt;
use bitcoin::secp256k1::{Secp256k1, All};
use bitcoin::bip32::{
    DerivationPath, ExtendedPrivKey, Fingerprint
};
use bitcoin::Network;
use std::str::FromStr;

pub struct Signer {
    secp: Secp256k1<All>,
    xprv: ExtendedPrivKey,
    fingerprint: Fingerprint,
}

impl Signer {
    pub fn new(xprv_str: &str) -> anyhow::Result<Self> {
        let secp = Secp256k1::new();
        let xprv = ExtendedPrivKey::from_str(xprv_str)?;
        let fingerprint = xprv.fingerprint(&secp);

        Ok(Self { secp, xprv, fingerprint })
    }

    pub fn sign(&self, psbt: &mut Psbt) -> anyhow::Result<()> {
        for (i, input) in psbt.inputs.iter_mut().enumerate() {
            for (pk, (fingerprint, path)) in
                input.tap_key_origins.clone()
            {
                if fingerprint != self.fingerprint {
                    continue;
                }

                let child_xprv = self.xprv
                    .derive_priv(&self.secp, &path)?;

                let keypair = child_xprv
                    .to_keypair(&self.secp);

                // Sign the taproot key-path spend
                psbt.sign(&keypair, &self.secp)
                    .map_err(|(_, e)| {
                        anyhow::anyhow!("{:?}", e)
                    })?;

                println!(
                    "  Signed input {} with {}",
                    i, pk
                );
            }
        }
        Ok(())
    }
}

pub async fn broadcast_tx(hex_tx: &str) -> anyhow::Result<String> {
    let response = reqwest::Client::new()
        .post("https://mempool.space/testnet/api/tx")
        .body(hex_tx.to_owned())
        .send()
        .await?;

    Ok(response.text().await?)
}

use std::process::Command;

pub fn sign_with_hwi(fingerprint: &str, psbt_path: &str) -> anyhow::Result<String> {
    let output = Command::new("hwi")
        .args(["-f", fingerprint, "signtx", psbt_path])
        .output()?;

    Ok(String::from_utf8(output.stdout)?)
}

